{
  "findings": [
    {
      "ref": "[D539]",
      "area": "contact",
      "claim": "A parent can turn off experience chat and direct chat to prevent strangers from messaging their child.",
      "stance": "mitigation",
      "quote": "Under Experience chat, choose who your child can publicly text chat with. Choose from Everyone or No one."
    },
    {
      "ref": "[D539]",
      "area": "contact",
      "claim": "A parent can turn off direct chat to prevent strangers from sending direct messages.",
      "stance": "mitigation",
      "quote": "Under Direct chat, choose who can send your child a direct message in Roblox experiences. Choose from Everyone or No one."
    },
    {
      "ref": "[D539]",
      "area": "contact",
      "claim": "A parent can limit party communication to friends only to reduce contact with strangers.",
      "stance": "mitigation",
      "quote": "For children under 13, this is limited to Friends or No one."
    },
    {
      "ref": "[D539]",
      "area": "money",
      "claim": "Roblox allows in‑app purchases using real money and can set monthly spending limits.",
      "stance": "neutral",
      "quote": "Enter the amount you’re happy with your child spending on a monthly basis. Tap Update."
    },
    {
      "ref": "[D539]",
      "area": "money",
      "claim": "Roblox can notify parents about every transaction if spending notifications are enabled.",
      "stance": "mitigation",
      "quote": "Choose when you’d like to get notifications about your child spending on Roblox."
    },
    {
      "ref": "[D539]",
      "area": "data",
      "claim": "Roblox collects data about a child's online status and experiences they are playing.",
      "stance": "risk",
      "quote": "Choose who can see your child’s Online status and which experience/game they are currently in."
    },
    {
      "ref": "[D539]",
      "area": "data",
      "claim": "Roblox may share a child's inventory information with strangers if not limited.",
      "stance": "risk",
      "quote": "If a stranger can see your child’s inventory and notices there’s an item they want, they might try to manipulate your child to give it to them."
    },
    {
      "ref": "[D539]",
      "area": "age_gating",
      "claim": "Roblox requires age verification for teens to use Trusted Connections, but the process is not automatic.",
      "stance": "neutral",
      "quote": "Go to More > Settings > Account Info. Tap Verify My Age and follow the verification instructions."
    },
    {
      "ref": "[D539]",
      "area": "content",
      "claim": "A parent reports that strangers can try to manipulate a child to give them items from their inventory.",
      "stance": "risk",
      "quote": "If a stranger can see your child’s inventory and notices there’s an item they want, they might try to manipulate your child to give it to them."
    }
  ]
}
